{
  "description": "A large chimeric creature is shown in right-facing profile standing upright on two hind legs with two large wings fully outstretched to the sides. The upper front has a lion-like head with a thick shaggy mane, the chest and neck are covered in overlapping feather-like structures, the wings are broad and heavily feathered in brown and tan tones, and the torso, hind legs and long tail are covered in tan fur with dark rosette spots. The tail ends in a dark tuft and curves in a hook shape. The overall posture is upright and alert, with the head turned slightly to the right and the wings held open.",
  "parts": [
    {
      "part": "head",
      "looks_like": "lion-like head in right profile with a tan and light brown muzzle, dark pinkish-brown nose, yellow eye with dark pupil, white fur on the chin and lower lip, small dark mouth line and whisker pores, located at the top front of the body above the feathered chest"
    ,
      "where": "top front of the body"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with light tan outer fur and darker interior, set close together on top of the head",
      "where": "on top of the head within the mane, one fully visible in profile and the second partially visible behind it"
    },
    {
      "part": "mane",
      "looks_like": "thick shaggy ruff of long hair in mixed light tan and medium brown, tousled and layered around the head and neck",
      "where": "encircling the back, top and sides of the head and extending down the back of the neck to the feathered chest"
    },
    {
      "part": "legs",
      "looks_like": "two thick muscular hind legs covered in short tan fur with dark rosette spots, bent at the hock joint in a digitigrade stance",
      "where": "at the lower rear and center of the body, extending from the spotted torso to the ground"
    },
    {
      "part": "feet",
      "looks_like": "large feline paws with rounded toes, light tan pads and short light claws, with spotted fur extending onto the top of the foot",
      "where": "at the ends of the two hind legs, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long slender tail covered in tan fur with small dark spots, ending in a bushy dark brown to black tuft, curved downward from the rump then looping upward in a hook",
      "where": "extending from the rear of the torso at the lower left of the image"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with layered flight feathers, base color tan and golden-brown with darker brown and black tips on the outer primaries and mottled patterning on the underside",
      "where": "attached at the shoulder area on the left and right sides of the upper torso, outstretched horizontally"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping leaf-shaped feathers in tan and brown with darker brown edges, with larger pointed feathers on the lower chest tipped with dark brown and white",
      "where": "covering the entire surface of both wings and forming a ruff across the front and sides of the neck and upper chest below the mane"
    },
    {
      "part": "markings",
      "looks_like": "numerous dark brown to black rosette spots with broken circular outlines and solid centers on a pale tan to golden background, varying in size across the body",
      "where": "covering the torso, sides, hind legs and tail, densest on the back and upper legs"
    }
  ],
  "attached_objects": [],
  "animals": ["lion", "leopard", "eagle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0
}
